20	) -> Result<SettlementEvent, ForgeError> {
21	    let mut basis = Vec::new();
22	    let (status, review_required) = if claim.authority_verdicts.contains(&Verdict::Escalate) {
23	        basis.push("authority_escalate".into());
24	        (SettlementStatus::Escalated, true)
25	    } else if claim.authority_verdicts.contains(&Verdict::Deny) {
26	        basis.push("authority_deny".into());
27	        (SettlementStatus::Rejected, false)
28	    } else {
29	        basis.push("authority_allow".into());
30	        match &claim.execution {
31	            None => (SettlementStatus::Rejected, false),
32	            Some(execution) => match execution.status {
33	                ExecutionStatus::SpawnFailed => {
34	                    basis.push("spawn_failed".into());
35	                    (SettlementStatus::Rejected, false)
36	                }
37	                ExecutionStatus::TimedOut => {
38	                    basis.push("timed_out".into());
39	                    (SettlementStatus::Rejected, false)
40	                }
41	                ExecutionStatus::SandboxViolation => {
42	                    basis.push("jail_violation".into());
43	                    (SettlementStatus::Rejected, false)
44	                }
45	                ExecutionStatus::Completed => {
46	                    let mut accepted = true;
47	                    if claim.criteria.require_exit_zero {
48	                        let zero = execution.exit_code == Some(0);
49	                        basis.push(if zero { "exit_zero" } else { "exit_nonzero" }.into());
50	                        accepted &= zero;
51	                    }
52	                    for path in &claim.criteria.required_artifacts {
53	                        let present = safe_existing(workspace, path)
54	                            .is_ok_and(|candidate| candidate.is_file());
55	                        basis.push(format!(
56	                            "required_artifact_{}:{path}",
57	                            if present { "present" } else { "missing" }
58	                        ));
59	                        accepted &= present;
60	                    }
61	                    if let Some(needle) = &claim.criteria.stdout_must_contain {
62	                        let stdout = safe_existing(run_dir, &execution.stdout_path)?;
63	                        let matches = file_contains(&stdout, needle)?;
64	                        basis.push(
65	                            if matches {
66	                                "stdout_match"
67	                            } else {
68	                                "stdout_mismatch"
69	                            }
70	                            .into(),
71	                        );
72	                        accepted &= matches;
73	                    }
74	                    // Evaluator scores recorded as evidence (§10.6 — never standing).
75	                    for (name, score) in &claim.evaluator_scores {
76	                        basis.push(format!("evaluator_score:{name}={score}"));
77	                    }
78	                    // Batch settlement (§7.6).
79	                    if let Some(batch) = &claim.batch {
80	                        basis.push(format!("batch_pass_ratio:{}", batch.pass_ratio));
81	                        basis.push(format!("batch_threshold:{}", batch.min_pass_ratio));
82	                        basis.push(format!("batch_passed:{}/{}", batch.passed, batch.total));
83	                        if batch.pass_ratio < batch.min_pass_ratio {
84	                            basis.push("batch_below_threshold".into());
85	                            accepted = false;
86	                        }
87	                        // Write failing records to quarantine (never silently dropped).
88	                        if !batch.failures.is_empty() {
89	                            let q_dir = run_dir.join("quarantine");
90	                            std::fs::create_dir_all(&q_dir)
91	                                .map_err(|e| ForgeError::io("create quarantine dir", e))?;
92	                            let q_path = q_dir.join(format!("{}.jsonl", claim.plan_item_id));
93	                            let mut buf = Vec::new();
94	                            for failure in &batch.failures {
95	                                let line = serde_json::to_vec(failure)?;
96	                                buf.extend(line);
