98	                            }
99	                            std::fs::write(&q_path, buf)
100	                                .map_err(|e| ForgeError::io("write quarantine", e))?;
101	                        }
102	                    }
103	                    (
104	                        if accepted {
105	                            SettlementStatus::Accepted
106	                        } else {
107	                            SettlementStatus::Rejected
108	                        },
109	                        false,
110	                    )
111	                }
112	            },
113	        }
114	    };
115	    if claim.criteria_ref.is_none() {
